/* Integração sobre os módulos existentes. Preparar/cancelar não grava bases. */
(()=>{'use strict';const V=MartinsVendasObras,P=MartinsPersistenciaRdo,J=MartinsJornada,$=id=>document.getElementById(id);window.getOrcamentosVendasDb=()=>J.read(localStorage,V.QUOTES,INITIAL_ORCAMENTOS_VENDAS);window.saveOrcamentosVendasDb=rows=>J.write(localStorage,V.QUOTES,rows,localStorage.getItem(V.QUOTES));
const style=document.createElement('style');style.textContent='#vob-dialog{box-sizing:border-box;width:min(620px,calc(100vw - 20px));max-height:90vh;overflow:auto;border:1px solid #cbd5e1;border-radius:14px;padding:20px;color:#334155}#vob-dialog::backdrop{background:#020617bb}#vob-dialog h2{font-size:20px;font-weight:800;color:#0f172a}#vob-dialog label{display:block;font-size:13px;font-weight:700;margin:14px 0}#vob-dialog input,#vob-dialog select{display:block;width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:8px}#vob-dialog button,.vob-open{padding:11px 14px;min-height:44px;margin:5px 5px 5px 0;border-radius:8px;font-size:12px;font-weight:800;background:#0f172a;color:#fbbf24}#vob-dialog #vob-cancel{background:#e2e8f0;color:#334155}#vob-dialog p,.vob-link{font-size:12px;line-height:1.5}#vob-info{padding:12px;background:#f8fafc;border-radius:8px;white-space:pre-wrap}#vob-message{color:#92400e;white-space:pre-wrap}.vob-link{padding:10px;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;margin-top:10px}#vob-dialog [hidden]{display:none!important}';document.head.append(style);
const dialog=document.createElement('dialog');dialog.id='vob-dialog';dialog.setAttribute('aria-labelledby','vob-title');dialog.innerHTML='<h2 id="vob-title">Conferir venda e vínculo com a obra</h2><p id="vob-info"></p><label>Como registrar esta venda?<select id="vob-mode"><option value="nova_obra">Criar pré-cadastro de obra</option><option value="obra_existente">Vincular a uma obra existente</option><option value="sem_obra">Venda de balcão / sem obra</option></select></label><label id="vob-name-label">Nome do pré-cadastro<input id="vob-name" maxlength="160" autocomplete="off"></label><label id="vob-existing-label" hidden>Obra existente<select id="vob-existing"></select></label><p id="vob-explain"></p><p>A confirmação não emite nota fiscal, não baixa estoque e não registra pagamento. Datas, responsável técnico e demais detalhes da obra serão completados na Gestão.</p><p id="vob-message" role="status" aria-live="polite"></p><button id="vob-confirm" type="button">Confirmar venda e vínculo</button><button id="vob-cancel" type="button">Voltar sem alterar</button>';document.body.append(dialog);let context=null,busy=false;
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});function actor(){let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}const user=currentLoggedUser,identify=u=>String(u?.id||u?.usuario||u?.email||'');if(!V.canSell(user)||!session||!identify(user)||identify(session)!==identify(user)||session.status==='Inativo'||session.perfil!==user.perfil)throw Error('Entre com perfil autorizado a vendas (Master, Comercial/Vendas ou permissão explícita) para confirmar.');return user.usuario||user.email||user.nome;}
function mode(){const value=$('vob-mode').value;$('vob-name-label').hidden=value!=='nova_obra';$('vob-existing-label').hidden=value!=='obra_existente';$('vob-explain').textContent=value==='nova_obra'?'Cria uma obra em Planejamento com cliente e valor desta venda. Nenhuma obra existente será substituída.':value==='obra_existente'?'Acrescenta o vínculo ao histórico da obra selecionada, preservando contrato, cronograma e dados já cadastrados.':'Confirma a venda sem criar obra. O registro fica no histórico comercial.';}
function renderWorks(works){for(const key of Object.keys(dadosObras))if(!Object.hasOwn(works,key))delete dadosObras[key];Object.assign(dadosObras,structuredClone(works));for(const id of ['obra-select','gestao-obra-select','filtro-obra-hist','ped-obra-select']){const select=$(id);if(!select)continue;for(const name of Object.keys(works))if(![...select.options].some(x=>x.value===name))select.add(new Option(name,name));}}
function openWork(name){try{const fresh=P.snapshot(localStorage,V.WORKS,dadosObras).data;if(!Object.hasOwn(fresh,name))throw Error('A obra vinculada não está disponível. Confira a Gestão.');renderWorks(fresh);window.navegarParaSecao('gestao');const select=$('gestao-obra-select');if(select){select.value=name;select.dispatchEvent(new Event('change',{bubbles:true}));}if(typeof renderGestaoObra==='function')renderGestaoObra(name);$('gm-refresh')?.click();}catch(e){showToast(e.message,'warning');}}
function open(id){try{P.guard(localStorage,V.QUOTES);const q=V.unique(window.getOrcamentosVendasDb(),id),works=P.snapshot(localStorage,V.WORKS,dadosObras).data;V.validate(q);context={id,expected:P.canonical(q)};$('vob-info').textContent='Orçamento: '+(q.num||q.id)+'\nCliente: '+q.cliente+'\nEmpresa: '+(q.empresa||'Não informada')+'\nTotal conferido: '+money(q.total)+'\nSituação atual: '+q.status+(q.vendaIntegracao?'\nVínculo já confirmado: '+(q.vendaIntegracao.obra||'Venda sem obra'):'');$('vob-message').textContent=q.vendaIntegracao?'Uma confirmação anterior será reutilizada; não será criada outra obra.':'';$('vob-mode').value=q.vendaIntegracao?.modo||'nova_obra';$('vob-name').value='Obra — '+q.cliente+' — '+(q.num||q.id);$('vob-existing').replaceChildren(new Option('Selecione uma obra',''));for(const name of Object.keys(works).sort())$('vob-existing').add(new Option(name,name));$('vob-existing').value=q.vendaIntegracao?.obra||'';mode();for(const el of dialog.querySelectorAll('input,select'))el.disabled=Boolean(q.vendaIntegracao);window.renderListaOrcamentosVendas?.();dialog.showModal();}catch(e){showToast(e.message,'warning');window.renderListaOrcamentosVendas?.();if(P.hasPending(localStorage))window.martinsMostrarRecuperacao?.();}}
$('vob-mode').onchange=mode;$('vob-cancel').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{if(!busy)context=null;});
$('vob-confirm').onclick=async()=>{if(busy||!context)return;busy=true;$('vob-confirm').disabled=true;$('vob-cancel').disabled=true;const selected={mode:$('vob-mode').value,name:$('vob-name').value,existing:$('vob-existing').value},request={...context};for(const el of dialog.querySelectorAll('input,select'))el.disabled=true;let committed=false;try{const result=await P.withLock(navigator.locks,()=>{const by=actor();P.guard(localStorage,V.QUOTES);const q=P.snapshot(localStorage,V.QUOTES,INITIAL_ORCAMENTOS_VENDAS),w=P.snapshot(localStorage,V.WORKS,dadosObras),next=V.plan(q.data,w.data,request.id,request.expected,{...selected,actor:by});if(!next.unchanged){const writes=[{key:V.QUOTES,value:next.quotes,expected:q.raw}];if(P.canonical(next.works)!==P.canonical(w.data))writes.push({key:V.WORKS,value:next.works,expected:w.raw});window.martinsUltimaGravacaoVenda=P.commit(localStorage,writes,{actor:by});committed=true;}return next;});renderWorks(result.works);dialog.close();context=null;window.renderListaOrcamentosVendas();try{window.registrarAtividadeSistema?.((result.unchanged?'Conferiu vínculo já existente':'Confirmou venda e vínculo')+' do orçamento '+request.id+(result.meta.obra?' com '+result.meta.obra:' sem obra'),'Vendas');}catch{}showToast(result.unchanged?'Venda já integrada. Nenhuma obra duplicada.':result.meta.obra?'Venda confirmada e vinculada. Complete o cadastro na Gestão da Obra.':'Venda confirmada sem criar obra.');}catch(e){if(committed){showToast('Venda gravada; houve falha na atualização da tela. Recarregue antes de repetir. '+e.message,'warning');dialog.close();}else{$('vob-message').textContent=e.message;if(P.hasPending(localStorage)){dialog.close();window.martinsMostrarRecuperacao?.();}}}finally{busy=false;if(context)for(const el of dialog.querySelectorAll('input,select'))el.disabled=Boolean(window.getOrcamentosVendasDb().find(q=>q.id===context.id)?.vendaIntegracao);$('vob-confirm').disabled=false;$('vob-cancel').disabled=false;}};
window.converterOrcamentoEmVenda=open;window.alterarStatusOrcamentoVenda=function(id,status){if(V.saleStatuses.includes(status)){open(id);return;}try{const by=actor(),before=localStorage.getItem(V.QUOTES),rows=V.status(window.getOrcamentosVendasDb(),id,status,by);J.write(localStorage,V.QUOTES,rows,before);window.renderListaOrcamentosVendas();showToast('Situação atualizada. Vínculos de venda e obras anteriores permanecem preservados.');}catch(e){showToast(e.message,'warning');window.renderListaOrcamentosVendas?.();}};
const originalRender=window.renderListaOrcamentosVendas;window.renderListaOrcamentosVendas=function(...args){const result=originalRender.apply(this,args);const quotes=window.getOrcamentosVendasDb();for(const card of $('lista-orcamentos-vendas')?.children||[]){const id=card.querySelector('span.font-mono')?.textContent,q=quotes.find(x=>x.id===id);if(!q?.vendaIntegracao)continue;const box=document.createElement('div');box.className='vob-link';const text=document.createElement('p');text.textContent='Venda vinculada: '+(q.vendaIntegracao.obra||'balcão / sem obra')+' · Valor na confirmação: '+money(q.vendaIntegracao.valorConfirmado)+(V.saleStatuses.includes(q.status)?'':' · Situação alterada; vínculo histórico preservado.');box.append(text);if(q.vendaIntegracao.obra){const b=document.createElement('button');b.type='button';b.className='vob-open';b.textContent='Abrir Gestão da Obra';b.onclick=()=>openWork(q.vendaIntegracao.obra);box.append(b);}card.append(box);}return result;};window.martinsAbrirObraDaVenda=openWork;
})();
